'use strict';
// TEAZO evidence helper. Generated by the PowerShell evidence runner into the
// evidence directory. Reads test reports; never changes application source.
const fs = require('node:fs');
const path = require('node:path');
const { createRequire } = require('node:module');

const mode = process.argv[2];
const root = path.resolve(process.argv[3] || '.');
const repo = path.resolve(process.argv[4] || process.cwd());
const sections = [
  '01-Public-Menu-Catalog',
  '02-Customization-Cart',
  '03-Checkout-Payment-Links',
  '04-Orders-Payment-Status',
  '05-Contact-Notifications',
  '06-Gallery-Images',
  '07-Events',
  '08-Admin-Menu',
  '09-Admin-Accounts-Access',
  '10-Website-Content-Hours',
  '11-Dashboard-Analytics',
  '12-Shared-Components-Configuration'
];
const sectionData = new Map(sections.map(section => [section, {
  section, files: 0, passed: 0, failed: 0, other: 0, playwright: []
}]));
const overrides = {
  'app/(site)/delivery/page.test.tsx':'10-Website-Content-Hours',
  'app/(site)/static-menu/page.test.tsx':'01-Public-Menu-Catalog',
  'app/(site)/static-menu/static-menu-content.test.ts':'01-Public-Menu-Catalog',
  'app/(site)/static-menu/static-menu-content.test.tsx':'01-Public-Menu-Catalog',
  'app/(site)/content-removal.test.tsx':'10-Website-Content-Hours',
  'app/components/bubble-field.test.tsx':'12-Shared-Components-Configuration',
  'app/components/turnstile-widget.test.tsx':'05-Contact-Notifications',
  'app/lib/admin-origin.test.ts':'09-Admin-Accounts-Access',
  'app/lib/admin.test.ts':'09-Admin-Accounts-Access',
  'app/lib/cart-issues.test.ts':'02-Customization-Cart',
  'app/lib/email.test.ts':'05-Contact-Notifications',
  'app/lib/menu-item-validators.test.ts':'08-Admin-Menu',
  'app/lib/menu-upload.test.ts':'08-Admin-Menu',
  'app/lib/preloadable-component.test.tsx':'12-Shared-Components-Configuration',
  'app/lib/site-url.test.ts':'12-Shared-Components-Configuration',
  'app/lib/square-location.test.ts':'03-Checkout-Payment-Links',
  'app/lib/square-option-rules.test.ts':'02-Customization-Cart',
  'app/lib/square.test.ts':'03-Checkout-Payment-Links',
  'app/lib/turnstile.test.ts':'05-Contact-Notifications',
  'app/(site)/components/chunk-loading-and-recovery.test.tsx':'02-Customization-Cart',
  'app/(site)/components/menu-items-section.test.tsx':'01-Public-Menu-Catalog',
  'app/admin/components/confirm-delete-dialog.test.tsx':'08-Admin-Menu',
  'app/lib/queries/menu-documents.test.ts':'08-Admin-Menu',
  'app/lib/queries/rate-limit.test.ts':'03-Checkout-Payment-Links',
  'app/lib/queries/settings.test.ts':'09-Admin-Accounts-Access',
  'app/admin/settings/components/transfer-ownership-dialog.test.tsx':'09-Admin-Accounts-Access',
  'app/api/admin/settings/admins-api.test.ts':'09-Admin-Accounts-Access',
  'app/api/square/products/route.test.ts':'01-Public-Menu-Catalog',
  'app/api/admin/[id]/resend-invitation/route.test.ts':'09-Admin-Accounts-Access'
};
function write(file, content) {
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, content, 'utf8');
}
function saveJson(file, value) { write(file, JSON.stringify(value, null, 2)); }
function csvValue(value) {
  const s = String(value ?? '');
  return /[",\r\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
}
function writeCsv(file, headers, rows) {
  write(file, [headers, ...rows].map(row => row.map(csvValue).join(',')).join('\r\n') + '\r\n');
}
function cleanPath(name) {
  const p = String(name || '').replace(/\\/g, '/');
  const repoNormalized = repo.replace(/\\/g, '/').replace(/\/$/, '') + '/';
  if (p.toLowerCase().startsWith(repoNormalized.toLowerCase())) {
    return p.slice(repoNormalized.length);
  }
  if (p.startsWith('app/') || p.startsWith('e2e/')) return p;
  throw new Error(`Unrecognized test path: ${p}`);
}
function sectionForTest(file) {
  const p = file.toLowerCase();
  if (overrides[p]) return overrides[p];
  if (/checkout|idempotenc|payment-ownership|payment-link/.test(p)) return sections[2];
  if (/webhook|\/orders\/|order-lifecycle|order\/confirmation/.test(p)) return sections[3];
  if (/customiz|cart-context|cart-drawer|shopping-bag|\/cart\//.test(p)) return sections[1];
  if (/login|password|ownership-transfer|admin-account|admin-role|admin-perm|admin-invit|\/auth\/|\/admins\/|admin-table|\/session/.test(p)) return sections[8];
  if (/gallery|carousel|\/media|r2/.test(p)) return sections[5];
  if (/event|live-events/.test(p)) return sections[6];
  if (/contact|notification|brevo/.test(p)) return sections[4];
  if (/analytics|dashboard|storage-usage|cleanup-analytics/.test(p)) return sections[10];
  if (/website-content|store-hour|holiday|business-hour|pickup-time|\/content\//.test(p)) return sections[9];
  if (/\/admin\/menu\/|admin-menu|menu-category|menu-form/.test(p)) return sections[7];
  if (/\/menu\/|public-menu|menu-catalog|catalog-loading|catalog-cache|\/catalog/.test(p)) return sections[0];
  return null;
}
function sectionForPlaywright(file, title) {
  const p = file.replace(/\\/g, '/').toLowerCase();
  if (p.endsWith('/static-menu.spec.ts')) return sections[0];
  if (p.endsWith('/delivery.spec.ts') || p.endsWith('/delivery-admin.spec.ts')) return sections[9];
  if (/\/admin-(login|password-flow|account-management|account-management-mobile)\.spec\.ts$/.test(p)) return sections[8];
  if (p.endsWith('/customizer-cart-checkout.spec.ts')) {
    return new Set([
      'displays cart items and subtotal',
      'updates totals when increasing quantity',
      'updates customization prices in the edit modal',
      'keeps the Shopping Bag usable on mobile'
    ]).has(title) ? sections[1] : sections[2];
  }
  return null;
}
function htmlEsc(s) {
  return String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}
async function imageFromData(file, title, stats, fileLines) {
  // Chromium was just used for the Playwright suite and is locally installed.
  const req = createRequire(path.join(repo, 'package.json'));
  const { chromium } = req('@playwright/test');
  const browser = await chromium.launch({ headless: true });
  try {
    const page = await browser.newPage({ viewport: { width: 1600, height: 950 }, deviceScaleFactor: 1 });
    const cols = fileLines.length > 14 ? 2 : 1;
    const data = fileLines.map(x=> `<div class="entry">${htmlEsc(x)}</div>`).join('');
    const doc = `<!doctype html><html><head><meta charset="utf-8"><style>
      * { box-sizing:border-box; }
      body { margin:0; background:#191c22; color:#eee; font:17px Consolas, 'Courier New', monospace; }
      #capture { width:1600px; background:#191c22; padding:29px 34px 40px; }
      h1 { font:700 27px Consolas, monospace; color:#91e5a1; margin:0 0 34px; }
      .stat { white-space:pre-wrap; margin:0 0 9px; font-size:17px; }
      h2 { font-size:19px; font-weight:400; margin:35px 0 13px; }
      .files { display:grid; grid-template-columns:repeat(${cols}, minmax(0, 1fr)); grid-auto-flow:column; grid-template-rows:repeat(${Math.ceil(fileLines.length / cols)}, auto); column-gap:24px; row-gap:9px; }
      .entry { white-space:nowrap; overflow:hidden; text-overflow:ellipsis; font-size:${cols===2?14:16}px; }
    </style></head><body><section id="capture"><h1>${htmlEsc(title)}</h1>${stats.map(x=>`<p class="stat">${htmlEsc(x)}</p>`).join('')}<h2>TEST FILE RESULTS:</h2><div class="files">${data}</div></section></body></html>`;
    await page.setContent(doc);
    await page.locator('#capture').screenshot({ path:file, animations:'disabled' });
  } finally { await browser.close(); }
}
function summarizeFile(t) {
  const all = Array.isArray(t.assertionResults) ? t.assertionResults : [];
  const passed = all.filter(x=>x.status==='passed').length;
  const failed = all.filter(x=>x.status==='failed').length;
  return { passed, failed, other:all.length-passed-failed };
}
function vitest() {
  const jsonPath = path.join(root,'overall-results.json');
  const r = JSON.parse(fs.readFileSync(jsonPath,'utf8'));
  if (!Array.isArray(r.testResults) || !r.testResults.length) throw new Error('Vitest JSON has no test files.');
  const grouped = new Map(sections.map(s=>[s,[]]));
  const unknown = [];
  const seen = new Set();
  for (const testResult of r.testResults) {
    const file = cleanPath(testResult.name);
    if (seen.has(file.toLowerCase())) throw new Error('Duplicate Vitest file: '+file);
    seen.add(file.toLowerCase());
    const section = sectionForTest(file);
    if (!section) { unknown.push(file); continue; }
    grouped.get(section).push({ file, testResult });
  }
  if (unknown.length) {
    write(path.join(root,'unclassified-vitest-files.txt'),unknown.join('\n')+'\n');
    throw new Error(`Unable to classify ${unknown.length} Vitest files; check unclassified-vitest-files.txt`);
  }
  const allFileRows = [], outputRows = [];
  for (const section of sections) {
    const files = grouped.get(section).sort((a,b)=>a.file.localeCompare(b.file));
    const fileRows = [], cases = [];
    const folder = path.join(root,section);
    fs.mkdirSync(folder,{recursive:true});
    for (const x of files) {
      const { passed,failed,other } = summarizeFile(x.testResult);
      fileRows.push({file:x.file, passed,failed,other});
      allFileRows.push([section,x.file,passed,failed,other]);
      for (const t of x.testResult.assertionResults || []) {
        cases.push([x.file,t.fullName,t.status,t.duration||0,(t.failureMessages||[]).join(' | ')]);
      }
    }
    const passed=fileRows.reduce((s,x)=>s+x.passed,0);
    const failed=fileRows.reduce((s,x)=>s+x.failed,0);
    const other=fileRows.reduce((s,x)=>s+x.other,0);
    Object.assign(sectionData.get(section),{files:files.length,passed,failed,other});
    outputRows.push([section,files.length,passed,failed,other]);
    saveJson(path.join(folder,'feature-results.json'),{section,testResults:files.map(x=>x.testResult)});
    writeCsv(path.join(folder,'test-files.csv'),['File','Passed','Failed','Other'],fileRows.map(x=>[x.file,x.passed,x.failed,x.other]));
    writeCsv(path.join(folder,'test-cases.csv'),['File','Test','Status','DurationMs','FailureDetails'],cases);
  }
  const totalPassed=outputRows.reduce((s,x)=>s+x[2],0), totalFailed=outputRows.reduce((s,x)=>s+x[3],0), totalOther=outputRows.reduce((s,x)=>s+x[4],0);
  if (totalPassed!==r.numPassedTests || totalFailed!==r.numFailedTests || seen.size!==r.testResults.length || totalPassed+totalFailed+totalOther!==r.numTotalTests) {
    throw new Error(`Vitest totals do not reconcile with JSON: sections ${totalPassed}/${totalFailed}/${totalOther}, report ${r.numPassedTests}/${r.numFailedTests}/${r.numTotalTests}`);
  }
  writeCsv(path.join(root,'test-file-to-section-map.csv'),['Section','TestFile','Passed','Failed','Other'],allFileRows);
  writeCsv(path.join(root,'section-summary.csv'),['Section','TestFiles','Passed','Failed','Other'],outputRows);
  saveJson(path.join(root,'vitest-summary.json'),{files:seen.size,total:r.numTotalTests,passed:totalPassed,failed:totalFailed,other:totalOther,sections:outputRows});
  console.log(`VITEST: ${totalPassed}/${r.numTotalTests} passed across ${seen.size} files; all assigned to 12 sections.`);
  for (const x of outputRows) console.log(`${x[0]}: ${x[2]} tests, ${x[1]} files`);
}
function playwright() {
  const jsonPath=path.join(root,'Playwright','playwright-results.json');
  const r=JSON.parse(fs.readFileSync(jsonPath,'utf8'));
  const cases=[],unmapped=[];
  function walk(suite,inheritedFile='') {
    if (!suite) return;
    const filename=String(suite.file||inheritedFile);
    for (const spec of suite.specs || []) {
      const file=String(spec.file||filename).replace(/\\/g,'/');
      const fullFile= file.startsWith('e2e/') ? file : `e2e/${file}`;
      for (const t of spec.tests||[]) {
        const section=sectionForPlaywright(fullFile, spec.title);
        if (!section) {unmapped.push(`${fullFile}: ${spec.title}`);continue;}
        const result=(t.results||[]).at(-1)||{};
        cases.push({section,file:fullFile,title:spec.title,status:t.status||result.status||'unknown',resultStatus:result.status||'unknown',attachments:result.attachments||[]});
      }
    }
    for (const sub of suite.suites||[]) walk(sub,filename);
  }
  for (const s of r.suites||[]) walk(s);
  if (unmapped.length) {
    write(path.join(root,'Playwright','unclassified-playwright-tests.txt'),unmapped.join('\n')+'\n');
    throw new Error(`${unmapped.length} unclassified Playwright tests`);
  }
  if (!cases.length) throw new Error('No Playwright tests found in JSON.');
  const total=cases.length, passed=cases.filter(x=>x.status==='expected').length,
    failed=cases.filter(x=>x.status==='unexpected'||x.status==='flaky').length,
    skipped=cases.filter(x=>x.status==='skipped').length;
  const allSpecs=new Set(cases.map(x=>x.file));
  const stats=(r.stats||{});
  if (stats.expected!==undefined && stats.expected!==passed) {
    throw new Error(`Playwright JSON stats expected=${stats.expected} but mapped passed=${passed}`);
  }
  for (const section of sections) {
    const scases=cases.filter(x=>x.section===section);
    const folder=path.join(root,section);
    if (!scases.length) continue;
    const dir=path.join(folder,'playwright-screenshots');
    fs.mkdirSync(dir,{recursive:true});
    for (let i=0;i<scases.length;i++) {
      const c=scases[i];
      for (let a=0;a<c.attachments.length;a++) {
        const att=c.attachments[a];
        if (att.contentType!=='image/png' || !att.path) continue;
        const source=path.isAbsolute(att.path)?att.path:path.resolve(repo,att.path);
        if (!fs.existsSync(source)) continue;
        const stem=c.title.replace(/[^A-Za-z0-9-]+/g,'-').slice(0,65);
        fs.copyFileSync(source,path.join(dir,`${String(i+1).padStart(3,'0')}-${stem}-${a+1}.png`));
      }
    }
    const count=scases.filter(x=>x.status==='expected').length;
    const unique=new Set(scases.map(x=>x.file)).size;
    saveJson(path.join(folder,'playwright-section-results.json'),scases.map(x=>({file:x.file,test:x.title,status:x.status})));
    sectionData.get(section).playwright={passed:count,total:scases.length,files:unique};
  }
  writeCsv(path.join(root,'Playwright','playwright-test-to-section-map.csv'),
    ['Section','File','Test','Status','ResultStatus'],cases.map(x=>[x.section,x.file,x.title,x.status,x.resultStatus]));
  saveJson(path.join(root,'playwright-summary.json'),{passed,failed,skipped,total,files:allSpecs.size,stats,bySection:sections.map(s=>({section:s,tests:cases.filter(x=>x.section===s).length}))});
  console.log(`PLAYWRIGHT: ${passed}/${total} passed, ${failed} failed, ${skipped} skipped across ${allSpecs.size} files.`);
}
async function renderImages() {
  const vit=JSON.parse(fs.readFileSync(path.join(root,'vitest-summary.json'),'utf8'));
  for (const row of vit.sections) {
    const [section,files,passed,failed,other]=row;
    const folder=path.join(root,section);
    const csv=fs.readFileSync(path.join(folder,'test-files.csv'),'utf8').trim().split(/\r?\n/).slice(1);
    const lines=csv.map(line=>{
      // File names in this codebase have no commas or double-quotes.
      const p=line.split(',');
      return `${p[0].replace(/^app\//,'')} | P:${p[1]} F:${p[2]} Other:${p[3]}`;
    });
    await imageFromData(path.join(folder,'test-evidence.png'),section,
      [`PASSED: ${passed}   FAILED: ${failed}   OTHER: ${other}`,`Test files: ${files}`],lines);
    const pwResult=path.join(folder,'playwright-section-results.json');
    if (fs.existsSync(pwResult)) {
      const cases=JSON.parse(fs.readFileSync(pwResult,'utf8'));
      const ok=cases.filter(x=>x.status==='expected').length;
      const filesCount=new Set(cases.map(x=>x.file)).size;
      await imageFromData(path.join(folder,'playwright-evidence.png'),`Playwright - ${section}`,
        [`PASSED: ${ok}   FAILED/OTHER: ${cases.length-ok}`,`Test files: ${filesCount}`],
        cases.map(c=>`${c.test} | ${c.status}`));
    }
  }
  await imageFromData(path.join(root,'overall-test-evidence.png'), 'TEAZO - Complete Vitest Results',
    [`PASSED: ${vit.passed}   FAILED: ${vit.failed}   OTHER: ${vit.other}`,`Test files: ${vit.files}`],
    vit.sections.map(([name,files,passed,failed,other])=>`${name} | P:${passed} F:${failed} Other:${other}`));
  const pwSummaryFile=path.join(root,'playwright-summary.json');
  if (fs.existsSync(pwSummaryFile)) {
    const pw=JSON.parse(fs.readFileSync(pwSummaryFile,'utf8'));
    await imageFromData(path.join(root,'overall-playwright-evidence.png'), 'TEAZO - Complete Playwright Results',
      [`PASSED: ${pw.passed}   FAILED: ${pw.failed}   SKIPPED: ${pw.skipped}`,`Test files: ${pw.files}`],
      pw.bySection.filter(x=>x.tests>0).map(x=>`${x.section} | ${x.tests} tests`));
  }
  console.log('Created overall and per-section evidence PNGs.');
}
function report() {
  const issues=[];
  const vitPath=path.join(root,'vitest-summary.json');
  const pwPath=path.join(root,'playwright-summary.json');
  const vit=fs.existsSync(vitPath)?JSON.parse(fs.readFileSync(vitPath,'utf8')):null;
  const pw=fs.existsSync(pwPath)?JSON.parse(fs.readFileSync(pwPath,'utf8')):null;
  const meta=fs.existsSync(path.join(root,'run-metadata.json'))?JSON.parse(fs.readFileSync(path.join(root,'run-metadata.json'),'utf8')):{};
  const s=[];
  s.push('TEAZO FULL TEST EVIDENCE - RUN SUMMARY',`Branch: ${meta.branch||'unknown'}`,`Commit: ${meta.commit||'unknown'}`,`Run: ${meta.started||'unknown'}`);
  s.push('');
  if (vit) {
    s.push(`Vitest: ${vit.passed}/${vit.total} passed across ${vit.files} files; ${vit.failed} failed, ${vit.other} other`);
    if (vit.passed!==vit.total) issues.push('Vitest did not fully pass');
  } else { s.push('Vitest evidence: incomplete');issues.push('Vitest evidence incomplete'); }
  if (pw) {
    s.push(`Playwright: ${pw.passed}/${pw.total} passed across ${pw.files} files; ${pw.failed} failed, ${pw.skipped} skipped`);
    if(pw.passed!==pw.total) issues.push('Playwright did not fully pass');
  } else { s.push('Playwright evidence: incomplete');issues.push('Playwright evidence incomplete'); }
  s.push('');
  if (vit) {
    s.push('COPY INTO SYSTEM TEST REPORT (.7 RESULTS):');
    for (let i=0;i<vit.sections.length;i++) {
      const [section,files,passed,failed,other]=vit.sections[i];
      let line=`${i+1}.7 Results: ${passed}/${passed+failed+other} Vitest tests passed across ${files} test files.`;
      if(pw) {
        const pwFile=path.join(root,section,'playwright-section-results.json');
        if(fs.existsSync(pwFile)) {
          const cases=JSON.parse(fs.readFileSync(pwFile,'utf8'));
          const good=cases.filter(x=>x.status==='expected').length;
          const unique=new Set(cases.map(x=>x.file)).size;
          line+=` Additionally, ${good}/${cases.length} Playwright tests passed across ${unique} test file(s).`;
        }
      }
      s.push(line);
    }
    s.push('');
  }
  s.push(`All checks passed: ${issues.length===0}`, 'ISSUES:');
  s.push(...(issues.length?issues:['None']));
  write(path.join(root,'run-summary.txt'),s.join('\r\n')+'\r\n');
  console.log(s.slice(0,8).join('\n'));
}
async function main() {
  if (!['vitest','playwright','images','report'].includes(mode)) throw new Error(`Unknown evidence operation: ${mode}`);
  if(mode==='vitest')vitest();
  if(mode==='playwright')playwright();
  if(mode==='images')await renderImages();
  if(mode==='report')report();
}
main().catch(err=>{console.error('Evidence helper failed:',err?.stack||err);process.exitCode=1;});